INSERT INTO places (id, name, cat, description, lat, lng, address) VALUES
  ('a0000001-0000-0000-0000-000000000001', 'Museo de Medicina Laboral', 'museo', 'Historia de la salud minera. Exhibe instrumentos médicos del siglo XIX y XX utilizados en los hospitales mineros de la región.', 20.1381, -98.6742, 'Camino Real a Pachuca s/n, Real del Monte'),
  ('a0000001-0000-0000-0000-000000000002', 'Panteón Inglés', 'historico', 'Cementerio de la comunidad británica de Cornualles. Construido en 1862, todas sus tumbas apuntan hacia el Mar del Norte.', 20.1396, -98.6725, 'Cerro del Hiloche, Real del Monte'),
  ('a0000001-0000-0000-0000-000000000003', 'Mina de Acosta', 'mineria', 'Museo de sitio minero. Operó desde el siglo XVIII hasta 1985. Los visitantes pueden descender por su socavón original y explorar túneles de extracción de plata.', 20.1367, -98.6702, 'Camino Real a Pachuca, Real del Monte'),
  ('a0000001-0000-0000-0000-000000000004', 'Parroquia de Nuestra Señora de la Asunción', 'arquitectura', 'Templo del siglo XVIII con retablos barrocos. Es el principal recinto religioso del municipio.', 20.1386, -98.6737, 'Plaza de la Constitución, Centro'),
  ('a0000001-0000-0000-0000-000000000005', 'Museo del Paste', 'gastronomia', 'Historia del platillo emblemático de Real del Monte. Recorrido por la tradición pasteuril desde su origen en Cornualles.', 20.1379, -98.6731, 'Calle Hidalgo 12, Centro'),
  ('a0000001-0000-0000-0000-000000000006', 'Plaza de la Constitución', 'plaza', 'Centro neurálgico del pueblo. Rodeada de edificios históricos, quiosco central y actividad cultural constante.', 20.1384, -98.6735, 'Plaza de la Constitución, Centro'),
  ('a0000001-0000-0000-0000-000000000007', 'Museo de Sitio Mina de Acosta', 'museo', 'Recorrido subterráneo por la mina más emblemática de Real del Monte. Maquinaria victoriana y castillo de malacate.', 20.1365, -98.6700, 'Camino Real a Pachuca s/n'),
  ('a0000001-0000-0000-0000-000000000008', 'Casa de la Cultura', 'cultura', 'Centro cultural con exposiciones, talleres y eventos artísticos. Alberga la memoria histórica del municipio.', 20.1389, -98.6740, 'Calle Benito Juárez 5, Centro'),
  ('a0000001-0000-0000-0000-000000000009', 'Palacio Municipal', 'arquitectura', 'Edificio del siglo XIX con arquitectura típica de la región. Sede del gobierno municipal.', 20.1382, -98.6733, 'Plaza de la Constitución 1, Centro'),
  ('a0000001-0000-0000-0000-000000000010', 'Capilla de Nuestra Señora del Rosario', 'arquitectura', 'Capilla del siglo XVIII con hermosos retablos dorados. Joya del barroco novohispano.', 20.1375, -98.6728, 'Calle del Rosario, Centro'),
  ('a0000001-0000-0000-0000-000000000011', 'Prismas Basálticos', 'naturaleza', 'Formación geológica de columnas de basalto de hasta 30 metros de altura. Maravilla natural a 15 minutos de Real del Monte.', 20.1185, -98.6874, 'Santa María Regla, Huasca de Ocampo'),
  ('a0000001-0000-0000-0000-000000000012', 'Peña del Aire', 'naturaleza', 'Mirador natural con vista panorámica del valle. Ideal para senderismo y fotografía.', 20.1250, -98.6780, 'Carretera Real del Monte-Huasca')
